ALTER TABLE public.resource_container_samples ADD CONSTRAINT resource_container_samples_finite CHECK((ts IS NULL OR (ts>=0 AND ts<=253402300799)) AND (mem_used_mb IS NULL OR (mem_used_mb>=0 AND mem_used_mb<'Infinity'::double precision)) AND (mem_limit_mb IS NULL OR (mem_limit_mb>=0 AND mem_limit_mb<'Infinity'::double precision)) AND (cpu_seconds IS NULL OR (cpu_seconds>=0 AND cpu_seconds<'Infinity'::double precision)) AND (cpu_pct IS NULL OR (cpu_pct>=0 AND cpu_pct<'Infinity'::double precision)));
